import React, { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css'; // Asegura que el CSS de Leaflet se cargue correctamente
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Home from './pages/Home';
import AdminDashboard from './pages/AdminDashboard';
import EmployeeDashboard from './pages/EmployeeDashboard';
import AdminUsers from './pages/AdminUsers';
import AdminCheckins from './pages/AdminCheckins'; // Asegúrate de importar esta página
import NotFound from './pages/NotFound';

const getUser = () => JSON.parse(localStorage.getItem('user'));

const ProtectedRoute = ({ element, allowedRoles }) => {
  const user = getUser();
  if (!user) return <Navigate to="/login" replace />;
  if (!allowedRoles.includes(user.role)) return <Navigate to="/home" replace />;
  return element;
};

const App = () => {
  return (
      <Router>
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/login" element={<Login />} />
          <Route path="/home" element={<Home />} />
          <Route
              path="/admin"
              element={<ProtectedRoute element={<AdminDashboard />} allowedRoles={['admin']} />}
          />
          <Route
              path="/admin/users"
              element={<ProtectedRoute element={<AdminUsers />} allowedRoles={['admin']} />}
          />
          <Route
              path="/admin/checkins"
              element={<ProtectedRoute element={<AdminCheckins />} allowedRoles={['admin']} />}
          />
          <Route
              path="/employee"
              element={<ProtectedRoute element={<EmployeeDashboard />} allowedRoles={['employee']} />}
          />
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Router>
  );
};

export default App;
